const wonkyFilterSrc = `
precision highp float;
varying vec2 vTexCoord;
uniform sampler2D tex0;

uniform float uTime;
uniform float uWonk;

float mod289(float x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
vec4 mod289(vec4 x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
vec4 perm(vec4 x){return mod289(((x * 34.0) + 1.0) * x);}

float noise(vec3 p){
  vec3 a = floor(p);
  vec3 d = p - a;
  d = d * d * (3.0 - 2.0 * d);

  vec4 b = a.xxyy + vec4(0.0, 1.0, 0.0, 1.0);
  vec4 k1 = perm(b.xyxy);
  vec4 k2 = perm(k1.xyxy + b.zzww);

  vec4 c = k2 + a.zzzz;
  vec4 k3 = perm(c);
  vec4 k4 = perm(c + 1.0);

  vec4 o1 = fract(k3 * (1.0 / 41.0));
  vec4 o2 = fract(k4 * (1.0 / 41.0));

  vec4 o3 = o2 * d.z + o1 * (1.0 - d.z);
  vec2 o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);

  return o4.y * d.y + o4.x * (1.0 - d.y);
}

float noiseOctaves(vec3 n) {
  float res = 0.0;
  for (int octave = 0; octave < 3; octave++) {
      float scale = pow(2., float(octave));
      res += noise(n * scale) / scale;
  }
  return res;
}

float map(float value, float min1, float max1, float min2, float max2) {
  return min2 + (value - min1) * (max2 - min2) / (max1 - min1);
}

void main() {
	vec2 coord = vTexCoord;
	coord += vec2(
    map(noiseOctaves(vec3(coord.x*10., coord.y*10., uTime*0.001)), 0., 1., -1., 1.),
    map(noiseOctaves(vec3(coord.x*10., coord.y*10., uTime*0.001 + 1000.)), 0., 1., -1., 1.)
  ) * uWonk;
	gl_FragColor = texture2D(tex0, coord);
}
`

