let input
let inputWidth = 200
let buttonX, buttonY
const buttonWidth = 100
const buttonHeight = 40
let wonkyFilter
let bulgeFilter
let pleaseScale = 1.01
let finalFilter
let prevName

let phase = 0
let phaseStart = 0
let finalText = 'aaAAAaAAAAAAAAAAA'
let finalWonk = 0.2

const steps = [
	{
		handleChange: (v) => v,
		onEnter: () => {},
		onDraw: () => {},
	},
	{
		handleChange: (v) => v,
		onEnter: () => {},
		onExit: () => {
			if (textWidth(input.value()) < inputWidth-10) {
				phase--
			}
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			fill(lerpColor(color('red'), color('black'), map(millis(), phaseStart, phaseStart + 2000, 0, 1, true)))
			text('Name is not long enough to be valid.', width/2 - inputWidth/2, height/2 - 50)
		},
	},
	{
		handleChange: (v) => {
			if (random() < 0.8) {
				return v
			} else {
				const chars = v.split('')
				chars.splice(int(random(chars.length)), 1)
				return chars.join('')
			}
		},
		onEnter: () => {
			input.value(input.value().slice(0, 1))
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			text('Data corruption error. Please try again.', width/2 - inputWidth/2, height/2 - 50)
		},
	},
	{
		handleChange: (v) => {
			if (random() < 0.8) {
				return v
			} else {
				const chars = v.split('')
				chars.splice(int(random(chars.length)), 1)
				return chars.join('')
			}
		},
		onExit: () => {
			if (/^[a-zA-Z ]*$/.exec(input.value())) {
				phase--
			}
		},
		onEnter: () => {},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			fill(lerpColor(color('red'), color('black'), map(millis(), phaseStart, phaseStart + 2000, 0, 1, true)))
			text('Name needs more special characters.', width/2 - inputWidth/2, height/2 - 50)
		},
	},
	{
		handleChange: (v) => v,
		onEnter: () => {
			prevName = input.value()
		},
		onExit: () => {
			if (input.value() === prevName) {
				phase--
			}
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			text('Name does not pass the vibe check.', width/2 - inputWidth/2, height/2 - 50)
			wonkyFilter.setUniform('uTime', millis())
			wonkyFilter.setUniform('uWonk', 0.002)
			filter(wonkyFilter)
		},
	},
	{
		handleChange: (v) => {
			if (random() < 0.95) {
				return v
			} else {
				return v.split('').map(() => random('@#$#$3#$^^@#%%&^*'.split(''))).join('')
			}
		},
		onEnter: () => {},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			text('That is actually worse.', width/2 - inputWidth/2, height/2 - 50)
			wonkyFilter.setUniform('uTime', millis())
			wonkyFilter.setUniform('uWonk', 0.006)
			filter(wonkyFilter)
		},
	},
	{
		handleChange: (v) => v,
		onEnter: () => {},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			text('Please enter two-factor code.', width/2 - inputWidth/2, height/2 - 50)
		},
	},
	{
		handleChange: (v) => v,
		onEnter: () => {},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			text('Incorrect two-factor code.', width/2 - inputWidth/2, height/2 - 50)
			bulgeFilter.setUniform('uTime', millis()*1.2)
			bulgeFilter.setUniform('uWonk', 0.005)
			bulgeFilter.setUniform('bulgeLoc', [0.35, 0.32])
			filter(bulgeFilter)
		},
	},
	{
		handleChange: (v) => {
			if (pleaseScale < 5 && v === 'please') {
				return 'pleas'
			} else {
				return v
			}
		},
		onEnter: () => {},
		onExit: () => {
			if (pleaseScale < 15 && !/please/.exec(input.value())) {
				phase--
				pleaseScale *= 1.8
			}
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			fill(lerpColor(color('yellow'), color('red'), map(millis(), phaseStart, phaseStart + 2000, 0, 1, true)))
			text('s̸̫̭̘͂̓͛a̴̩̦͎͌̆̎͝y̵̙̫̗̼̔͝ ̵̱̹̻̊ͅp̵̤̯̓̂͠l̶̮̥̑̋ĕ̷̜͇̒̋á̴̟̦͈͝s̷̩̥̀̌ě̶̢͔͚͈̓͆', width/2 - inputWidth/2 + random(-pleaseScale,pleaseScale), height/2 - 50 + random(-pleaseScale,pleaseScale))
			bulgeFilter.setUniform('uTime', millis()*1.2)
			bulgeFilter.setUniform('uWonk', 0.01)
			bulgeFilter.setUniform('bulgeLoc', [0.15, 0.32])
			filter(bulgeFilter)
		},
	},
	{
		handleChange: (v) => {
			if (phase === 9) return 'Raphaël'
			return v
		},
		onEnter: () => {},
		onExit: () => {
			if (input.value() !== 'Raphaël') {
				phase--
			}
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			fill(lerpColor(color('red'), color('black'), map(millis(), phaseStart, phaseStart + 2000, 0, 1, true)))
			text('Name is not Raphaël.', width/2 - inputWidth/2, height/2 - 50)
		},
	},
	{
		handleChange: (v) => v,
		onEnter: () => {},
		onExit: () => {
			phase--
			finalWonk += 0.01
			finalText = ''
			let numChars = int(random(4, 100))
			for (let i = 0; i < numChars; i++) {
				finalText += random('aaAAhAA?!@'.split(''))
			}
		},
		onDraw: () => {
			textAlign(LEFT, BOTTOM)
			fill(lerpColor(color('yellow'), color('red'), map(millis(), phaseStart, phaseStart + 2000, 0, 1, true)))
			text(finalText, width/2 - inputWidth/2 + random(-pleaseScale,pleaseScale), height/2 - 50 + random(-pleaseScale,pleaseScale))
			finalFilter.setUniform('uTime', millis()*1.2)
			finalFilter.setUniform('uWonk', finalWonk)
			filter(finalFilter)
		},
	},
]

function setup() {
	createCanvas(600, 400);

	document.body.style.background = 'white'
	document.body.style.display = 'flex'
	document.body.style.alignItems = 'center'
	document.body.style.justifyContent = 'center'
	document.body.style.minHeight = '100%'

	input = createInput()
	input.position(windowWidth/2 - inputWidth/2, windowHeight/2)
	input.style('width', inputWidth + 'px')
	input.style('fontSize', '20px')
	input.style('padding', '5px')
	input.style('border', '0')
	input.style('box-sizing', 'border-box')
	input.style('fontFamily', 'sans-serif')
	input.style('opacity', 0.001)
	input.input(handleChange)

	buttonX = width/2 - inputWidth/2 + buttonWidth/2
	buttonY = height/2 + 65

	wonkyFilter = createFilterShader(wonkyFilterSrc)
	bulgeFilter = createFilterShader(bulgeFilterSrc)
	finalFilter = createFilterShader(finalFilterSrc)
}

function handleChange() {
	for (let i = 0; i <= min(phase, steps.length-1); i++) {
		input.value(steps[i].handleChange(input.value()))
	}
	if (textWidth(input.value()) > inputWidth - 10) {
		input.style('width', (textWidth(input.value()) + 10) + 'px')
	} else {
		input.style('width', inputWidth + 'px')
	}
}

function mouseOverButton() {
	return (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) >= buttonX - buttonWidth/2 &&
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) <= buttonX + buttonWidth/2 &&
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) >= buttonY - buttonHeight/2 &&
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) <= buttonY + buttonHeight/2
}

function mousePressed() {
	if (mouseOverButton()) {
		if (steps[phase] && steps[phase].onExit) {
			steps[phase].onExit()
		}
		phase++
		phaseStart = millis()
		if (steps[phase]) {
			steps[phase].onEnter()
		}
	}
}

function draw() {
	background(255)
	noStroke()
	fill(0)

	textSize(20)
	textAlign(LEFT, BOTTOM)
	text('Enter your full name:', width/2 - inputWidth/2, height/2-10)

	noStroke()
	fill(mouseOverButton() ? '#6AA1EC' : '#6889B6')
	rect(buttonX-buttonWidth/2, buttonY-buttonHeight/2, buttonWidth, buttonHeight, 4)
	textAlign(CENTER, CENTER)
	fill(255)
	text('Submit', buttonX, buttonY)

	push()
	translate(width/2 - inputWidth/2, height/2)
	fill(0)
	textAlign(LEFT, TOP)
	text(input.value(), 5, 5)

	noFill()
	stroke(0)
	rect(0, 0, inputWidth, 30)

	if (document.activeElement === input.elt) {
		const startIdx = input.elt.selectionStart
		const endIdx = input.elt.selectionEnd
		const startOff = 5 + textWidth(input.value().slice(0, startIdx))
		const endOff = 5 + textWidth(input.value().slice(0, endIdx))
		if (startIdx === endIdx) {
			noFill()
			stroke(0, frameCount % 60 < 30 ? 255 : 0)
			line(startOff, 5, startOff, 25)
		} else {
			noStroke()
			fill(100, 100, 255, 100)
			rect(startOff, 5, endOff - startOff, 20)
		}
	}
	pop()

	fill(0)
	if (steps[phase]) {
		steps[phase].onDraw()
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
